--
-- Name: v_assets_current; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_assets_current AS
 SELECT a.id,
    a.tag,
    a.name,
    a.manufacturer,
    a.model,
    a.rated_power_kw,
    a.status,
    lr.measured_at AS last_reading_at,
    lr.temperature_c AS last_temperature_c,
    lr.vibration_mm_s AS last_vibration_mm_s,
    lr.current_a AS last_current_a,
    lr.power_kw AS last_power_kw
   FROM (public.assets a
     LEFT JOIN LATERAL ( SELECT rc.id,
            rc.raw_id,
            rc.asset_id,
            rc.asset_tag,
            rc.measured_at,
            rc.temperature_c,
            rc.vibration_mm_s,
            rc.current_a,
            rc.voltage_v,
            rc.rpm,
            rc.power_kw,
            rc.quality_score,
            rc.flags,
            rc.processed_at
           FROM public.readings_clean rc
          WHERE (rc.asset_id = a.id)
          ORDER BY rc.measured_at DESC
         LIMIT 1) lr ON (true));


